contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address first, address second) internal {
        vm.assume(first != second);
        bool r1;
        try c.setOwner(first) returns (bool __r) { r1 = __r; } catch { return; }
        bool r2;
        try c.setOwner(second) returns (bool __r) { r2 = __r; } catch { return; }
        address current;
        try c.owner() returns (address __r) { current = __r; } catch { return; }
        assertTrue(r1 && r2 && current == second);
    }

    function testFuzz_run(address first, address second) public {
